"""Commands that work on the book itself: init, db, serve, account, tx, query, export, journal,
import, profile and rules."""
import os

from tallybook.accounts import valid_path
from tallybook.cli.core import (CliError, Opt, UsageError, command, parse_day, parse_int)
from tallybook.cli.render import json_out, table_out, tx_list_out
from tallybook.csvimport import parse_profile
from tallybook.currency import CURRENCIES
from tallybook.dates import format_date
from tallybook.errors import TallybookError
from tallybook.export import money_to_dict, transaction_to_dict, transactions_to_csv, transactions_to_json
from tallybook.journal import format_journal, format_transaction, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, parse_amount
from tallybook.rules import parse_rules


def _lines(lines):
    """Text of lines: each ends in one newline; no lines give no output."""
    return "".join(ln + "\n" for ln in lines)


def _with_final_newline(text):
    return text if text == "" or text.endswith("\n") else text + "\n"


# ---------------------------------------------------------------------------
# init and db
# ---------------------------------------------------------------------------
@command("init", usage="init", summary="create the book, or bring an older one up to date", needs_book=False)
def cmd_init(ctx, args):
    from tallybook.storage import LATEST_VERSION

    path = ctx.db_path
    existed = os.path.exists(path) and not os.path.isdir(path) and os.path.getsize(path) > 0
    store = ctx.open_book(create=True, allow_old=True)
    if not existed:
        return "created %s (version %d)\n" % (path, store.version)
    before = store.version
    if before < LATEST_VERSION:
        store.migrate()
        return "migrated %s from version %d to %d\n" % (path, before, store.version)
    return "%s is up to date (version %d)\n" % (path, before)


@command("db version", usage="db version", summary="print the schema version of the book")
def cmd_db_version(ctx, args):
    return "%d\n" % ctx.open_book(allow_old=True).version


@command("db migrate", usage="db migrate", summary="bring the book up to the newest schema version")
def cmd_db_migrate(ctx, args):
    from tallybook.storage import LATEST_VERSION

    store = ctx.open_book(allow_old=True)
    applied = store.migrate()
    if not applied:
        return "database is up to date (version %d)\n" % LATEST_VERSION
    return _lines("applied version %d" % v for v in applied)


@command("db info", usage="db info [--json]", summary="show the path, version and row counts of the book",
         opts=[Opt("json", "flag")])
def cmd_db_info(ctx, args):
    info = ctx.open_book().info()
    if args.flag("json"):
        return json_out(info)
    order = ["path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"]
    return _lines("%s: %s" % (k, info[k]) for k in order)


@command("db check", usage="db check", summary="look for damage in the book file")
def cmd_db_check(ctx, args):
    problems = ctx.open_book().check()
    if not problems:
        return "ok\n"
    return _lines(problems), 1


@command("db backup", usage="db backup DEST", summary="copy the book to the new file DEST",
         pos=[("DEST", "1")])
def cmd_db_backup(ctx, args):
    dest = args.pos[0]
    ctx.open_book().backup(dest)
    return "backed up to %s\n" % dest


@command("serve", usage="serve [--host HOST] [--port N]", summary="serve the book over HTTP",
         opts=[Opt("host"), Opt("port", metavar="N")])
def cmd_serve(ctx, args):
    host = args.get("host", "127.0.0.1")
    port = 8765
    if args.opts.get("port") is not None:
        port = parse_int(args.get("port"), "port")
        if port > 65535:
            raise CliError("invalid port '%s': the largest is 65535" % args.get("port"))
    ctx.open_book().close()
    from tallybook.api import server

    try:
        server.serve(ctx.db_path, host, port, today=ctx._today)
    except OSError as err:
        raise CliError("cannot serve on %s:%d: %s" % (host, port, err.strerror or err))
    return ""


# ---------------------------------------------------------------------------
# accounts
# ---------------------------------------------------------------------------
def _account_dict(acc):
    return {"path": acc.path, "type": acc.type, "currency": acc.currency,
