"""Commands that work on the book itself: init, db, serve, account, tx, query, export, journal,
import, profile and rules."""
import os

from tallybook.accounts import valid_path
from tallybook.cli.core import (CliError, Opt, UsageError, command, parse_day, parse_int)
from tallybook.cli.render import json_out, table_out, tx_list_out
from tallybook.csvimport import parse_profile
from tallybook.currency import CURRENCIES
from tallybook.dates import format_date
from tallybook.errors import TallybookError
from tallybook.export import money_to_dict, transaction_to_dict, transactions_to_csv, transactions_to_json
from tallybook.journal import format_journal, format_transaction, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, parse_amount
from tallybook.rules import parse_rules


def _lines(lines):
    """Text of lines: each ends in one newline; no lines give no output."""
    return "".join(ln + "\n" for ln in lines)


def _with_final_newline(text):
    return text if text == "" or text.endswith("\n") else text + "\n"


# ---------------------------------------------------------------------------
# init and db
# ---------------------------------------------------------------------------
@command("init", usage="init", summary="create the book, or bring an older one up to date", needs_book=False)
def cmd_init(ctx, args):
    from tallybook.storage import LATEST_VERSION

    path = ctx.db_path
    existed = os.path.exists(path) and not os.path.isdir(path) and os.path.getsize(path) > 0
    store = ctx.open_book(create=True, allow_old=True)
    if not existed:
        return "created %s (version %d)\n" % (path, store.version)
    before = store.version
    if before < LATEST_VERSION:
        store.migrate()
        return "migrated %s from version %d to %d\n" % (path, before, store.version)
    return "%s is up to date (version %d)\n" % (path, before)


@command("db version", usage="db version", summary="print the schema version of the book")
def cmd_db_version(ctx, args):
    return "%d\n" % ctx.open_book(allow_old=True).version


@command("db migrate", usage="db migrate", summary="bring the book up to the newest schema version")
def cmd_db_migrate(ctx, args):
    from tallybook.storage import LATEST_VERSION

    store = ctx.open_book(allow_old=True)
    applied = store.migrate()
    if not applied:
        return "database is up to date (version %d)\n" % LATEST_VERSION
    return _lines("applied version %d" % v for v in applied)


@command("db info", usage="db info [--json]", summary="show the path, version and row counts of the book",
         opts=[Opt("json", "flag")])
def cmd_db_info(ctx, args):
    info = ctx.open_book().info()
    if args.flag("json"):
        return json_out(info)
    order = ["path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"]
    return _lines("%s: %s" % (k, info[k]) for k in order)


@command("db check", usage="db check", summary="look for damage in the book file")
def cmd_db_check(ctx, args):
    problems = ctx.open_book().check()
    if not problems:
        return "ok\n"
    return _lines(problems), 1


@command("db backup", usage="db backup DEST", summary="copy the book to the new file DEST",
         pos=[("DEST", "1")])
def cmd_db_backup(ctx, args):
    dest = args.pos[0]
    ctx.open_book().backup(dest)
    return "backed up to %s\n" % dest


@command("serve", usage="serve [--host HOST] [--port N]", summary="serve the book over HTTP",
         opts=[Opt("host"), Opt("port", metavar="N")])
def cmd_serve(ctx, args):
    host = args.get("host", "127.0.0.1")
    port = 8765
    if args.opts.get("port") is not None:
        port = parse_int(args.get("port"), "port")
        if port > 65535:
            raise CliError("invalid port '%s': the largest is 65535" % args.get("port"))
    ctx.open_book().close()
    from tallybook.api import server

    try:
        server.serve(ctx.db_path, host, port, today=ctx._today)
    except OSError as err:
        raise CliError("cannot serve on %s:%d: %s" % (host, port, err.strerror or err))
    return ""


# ---------------------------------------------------------------------------
# accounts
# ---------------------------------------------------------------------------
def _account_dict(acc):
    return {"path": acc.path, "type": acc.type, "currency": acc.currency,
            "opened": None if acc.opened is None else format_date(acc.opened),
            "closed": None if acc.closed is None else format_date(acc.closed),
            "note": acc.note}


@command("account add", usage="account add PATH [--currency CUR] [--open DATE] [--note TEXT]",
         summary="add an account",
         opts=[Opt("currency", metavar="CUR"), Opt("open", metavar="DATE"), Opt("note", metavar="TEXT")],
         pos=[("PATH", "1")])
def cmd_account_add(ctx, args):
    opened = parse_day(args.get("open")) if args.opts.get("open") is not None else None
    store = ctx.open_book()
    store.add_account(args.pos[0], None, args.opts.get("currency"), opened, args.get("note", ""))
    return "added account %s\n" % args.pos[0]


@command("account list",
         usage="account list [--type TYPE] [--under PATH] [--currency CUR] [--open-only] [--json]",
         summary="list the accounts",
         opts=[Opt("type", metavar="TYPE"), Opt("under", metavar="PATH"), Opt("currency", metavar="CUR"),
               Opt("open-only", "flag"), Opt("json", "flag")])
def cmd_account_list(ctx, args):
    store = ctx.open_book()
    accounts = store.accounts(type=args.opts.get("type"), under=args.opts.get("under"),
                              currency=args.opts.get("currency"), include_closed=not args.flag("open-only"))
    if args.flag("json"):
        return json_out([_account_dict(a) for a in accounts])
    rows = [[a.path, a.type, a.currency, None if a.opened is None else format_date(a.opened),
             None if a.closed is None else format_date(a.closed), a.note] for a in accounts]
    return table_out(["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows, "llllll")


@command("account show", usage="account show PATH [--json]", summary="show one account and its balance",
         opts=[Opt("json", "flag")], pos=[("PATH", "1")])
def cmd_account_show(ctx, args):
    store = ctx.open_book()
    acc = store.get_account(args.pos[0])
    sums = store.ledger().rollup_balances().get(acc.path, {})
    balance = [Money(sums[c], c) for c in sorted(sums)]
    if args.flag("json"):
        out = _account_dict(acc)
        out["balance"] = [money_to_dict(m) for m in balance]
        return json_out(out)
    d = _account_dict(acc)
    lines = ["path: %s" % acc.path, "type: %s" % acc.type,
             "currency: %s" % (acc.currency or "any"),
             "opened: %s" % (d["opened"] or "none"),
             "closed: %s" % (d["closed"] or "none"),
             ("note: %s" % acc.note).rstrip(),
             "balance: %s" % (", ".join(str(m) for m in balance) or "none")]
    return _lines(lines)


@command("account close", usage="account close PATH [--on DATE]", summary="close an account",
         opts=[Opt("on", metavar="DATE")], pos=[("PATH", "1")])
def cmd_account_close(ctx, args):
    on = parse_day(args.get("on")) if args.opts.get("on") is not None else ctx.today
    ctx.open_book().close_account(args.pos[0], on)
    return "closed account %s on %s\n" % (args.pos[0], format_date(on))


# ---------------------------------------------------------------------------
# transactions
# ---------------------------------------------------------------------------
def parse_posting_arg(text):
    """One posting argument: ``ACCOUNT [AMOUNT CUR] [; note]``."""
    head, semi, rest = text.partition(";")
    note = rest.strip() if semi else ""
    parts = head.split()
    shape = "invalid posting '%s': write ACCOUNT or ACCOUNT AMOUNT CURRENCY, then an optional ; note" % text
    if len(parts) not in (1, 3):
        raise CliError(shape)
    if not valid_path(parts[0]):
        raise CliError("invalid account path '%s'" % parts[0])
    if len(parts) == 1:
        return Posting(parts[0], None, note)
    cur = parts[2]
    if cur not in CURRENCIES:
        raise CliError("unknown currency '%s'" % cur)
    try:
        minor = parse_amount(parts[1], cur)
        amount = Money(minor, cur)
    except TallybookError as err:
        raise CliError(err.message)
    except (ValueError, OverflowError):
        raise CliError("invalid amount '%s'" % (parts[1] if len(parts[1]) <= 60 else parts[1][:57] + "..."))
    return Posting(parts[0], amount, note)


def _template(args, payee, on):
    """The transaction described by the shared tx add / recurring add options."""
    postings = [parse_posting_arg(p) for p in args.many("posting")]
    return Transaction(on, payee, args.get("narration", ""), postings, tuple(args.many("tag")),
                       args.get("flag", "*"), None)


@command("tx add",
         usage="tx add PAYEE [--date DATE] [--narration TEXT] [--flag F] [--tag TAG]... [-p POSTING]... [--json]",
         summary="add a transaction",
         opts=[Opt("date", metavar="DATE"), Opt("narration", metavar="TEXT"), Opt("flag", metavar="F"),
               Opt("tag", "repeat", metavar="TAG"), Opt("posting", "repeat", short="-p", metavar="POSTING"),
               Opt("json", "flag")],
         pos=[("PAYEE", "1")])
def cmd_tx_add(ctx, args):
    on = parse_day(args.get("date")) if args.opts.get("date") is not None else ctx.today
    tx = _template(args, args.pos[0], on)
    stored = ctx.open_book().add_transaction(tx)
    if args.flag("json"):
        return json_out(transaction_to_dict(stored))
    return "added transaction %d\n" % stored.id


def _paging(args):
    limit = parse_int(args.get("limit"), "limit") if args.opts.get("limit") is not None else None
    offset = parse_int(args.get("offset"), "offset") if args.opts.get("offset") is not None else 0
    return limit, offset


@command("tx list", usage="tx list [--query QUERY] [--limit N] [--offset N] [--json]",
         summary="list transactions",
         opts=[Opt("query", metavar="QUERY"), Opt("limit", metavar="N"), Opt("offset", metavar="N"),
               Opt("json", "flag")])
def cmd_tx_list(ctx, args):
    limit, offset = _paging(args)
    txs = ctx.open_book().transactions(args.opts.get("query"), limit, offset)
    return tx_list_out(txs, args.flag("json"))


@command("tx show", usage="tx show ID [--json]", summary="show one transaction",
         opts=[Opt("json", "flag")], pos=[("ID", "1")])
def cmd_tx_show(ctx, args):
    tx_id = parse_int(args.pos[0], "transaction id")
    tx = ctx.open_book().get_transaction(tx_id)
    if args.flag("json"):
        return json_out(transaction_to_dict(tx))
    return "; id %d\n%s" % (tx.id, format_transaction(tx))


@command("tx delete", usage="tx delete ID", summary="delete a transaction", pos=[("ID", "1")])
def cmd_tx_delete(ctx, args):
    tx_id = parse_int(args.pos[0], "transaction id")
    ctx.open_book().delete_transaction(tx_id)
    return "deleted transaction %d\n" % tx_id


@command("query", usage="query QUERY [--limit N] [--offset N] [--json] [--count]",
         summary="list the transactions matching a query",
         opts=[Opt("limit", metavar="N"), Opt("offset", metavar="N"), Opt("json", "flag"),
               Opt("count", "flag")],
         pos=[("QUERY", "1")])
def cmd_query(ctx, args):
    limit, offset = _paging(args)
    store = ctx.open_book()
    if args.flag("count"):
        return "%d\n" % store.count_transactions(args.pos[0])
    return tx_list_out(store.transactions(args.pos[0], limit, offset), args.flag("json"))


# ---------------------------------------------------------------------------
# export and journals
# ---------------------------------------------------------------------------
@command("export", usage="export [--format csv|json|journal] [--query QUERY]",
         summary="print the transactions as CSV, JSON or the whole book as a journal",
         opts=[Opt("format", metavar="FORMAT"), Opt("query", metavar="QUERY")])
def cmd_export(ctx, args):
    fmt = args.get("format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise CliError("unknown export format '%s': use csv, json or journal" % fmt)
    if fmt == "journal" and args.opts.get("query") is not None:
        raise CliError("a journal export is the whole book and takes no --query")
    store = ctx.open_book()
    if fmt == "journal":
        return format_journal(store.journal())
    txs = store.transactions(args.opts.get("query"))
    return transactions_to_csv(txs) if fmt == "csv" else transactions_to_json(txs)


@command("journal export", usage="journal export", summary="print the whole book as journal text")
def cmd_journal_export(ctx, args):
    return format_journal(ctx.open_book().journal())


def _parse_file(path, text, parser):
    from tallybook.cli.core import wrap_input_errors

    return wrap_input_errors(path, parser, text)


@command("journal import", usage="journal import FILE", summary="add the contents of a journal file (- is standard input)",
         pos=[("FILE", "1")])
