                       ["row %s: %s" % (num, msg) for num, msg in outcome.errors])
    return "imported %d transactions, %d duplicates\n" % (len(outcome.added), len(outcome.duplicates))


@command("profile add", usage="profile add NAME FILE", summary="store an import profile from a file",
         pos=[("NAME", "1"), ("FILE", "1")])
def cmd_profile_add(ctx, args):
